<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import SkinPreview3D from '../components/SkinPreview3D.vue'
import axios from 'axios'
import { AlertTriangle, Download, ShieldCheck, Upload } from 'lucide-vue-next'
import { usePurchaseStore } from '../stores/purchase'
const purchaseStore = usePurchaseStore(); const API_URL = 'http://localhost:3001/api'; const token = ref(localStorage.getItem('mistraly_token') || localStorage.getItem('breeze_token')); const user = ref<any>(null); const pass = ref<any>(null); const discord = ref<any>(null); const skinFile = ref<File | null>(null); const variant = ref('default'); const statusMsg = ref('')
async function loadProfile() { if (!token.value) return; try { const [p, s] = await Promise.all([axios.get(`${API_URL}/user/profile`, { headers: { Authorization: `Bearer ${token.value}` } }), axios.get(`${API_URL}/pass/status`, { headers: { Authorization: `Bearer ${token.value}` } })]); user.value = p.data?.data; pass.value = s.data?.data } catch { localStorage.removeItem('mistraly_token')
          localStorage.removeItem('breeze_token'); token.value = null } try { discord.value = JSON.parse(localStorage.getItem('mistraly_discord') || localStorage.getItem('breeze_discord') || 'null') } catch {} }
function onFileSelect(e: Event) { skinFile.value = (e.target as HTMLInputElement).files?.[0] || null }
async function uploadSkin() { if (!skinFile.value || !token.value) return; const base64 = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result).split(',')[1]); reader.onerror = reject; reader.readAsDataURL(skinFile.value!) }); try { await axios.put(`${API_URL}/user/skin`, { skin_data: base64, variant: variant.value }, { headers: { Authorization: `Bearer ${token.value}` } }); statusMsg.value = 'Скин успешно обновлен!'; skinFile.value = null } catch { statusMsg.value = 'Ошибка при загрузке скина.' } }
const skinPreviewUrl = computed(() => user.value?.username ? `${API_URL}/uploads/skins/${user.value.username}.png` : undefined)
onMounted(loadProfile)
</script>
<template><main class="w-full flex-1 flex flex-col items-center justify-start page-bg bg-[var(--bg-page)] text-[var(--text-main)] px-4 py-12"><div class="w-full max-w-4xl"><div class="flex items-center justify-between mb-8 pb-6 border-b border-[var(--border-color)]"><div><span class="text-xs font-bold uppercase tracking-wider text-[#0099FF]">Личный кабинет</span><h1 class="font-heading text-3xl font-black text-[var(--text-main)] mt-1">{{ user?.username || discord?.discord_username || 'Игрок' }}</h1></div><span class="px-3 py-1 rounded-full bg-[var(--bg-card-hover)] border border-[var(--border-color)] text-xs font-semibold text-[var(--text-muted)]">{{ user?.role === 'admin' ? 'Администратор' : 'Игрок' }}</span></div><div v-if="!token" class="p-8 rounded-2xl bg-[var(--bg-card)] border border-[var(--border-color)] text-center flex flex-col items-center"><h3 class="font-heading text-lg font-bold text-[var(--text-main)] mb-2">Требуется авторизация</h3><p class="text-xs text-[var(--text-muted)] mb-6">Войдите через Discord, чтобы просмотреть профиль и загрузить скин.</p><button @click="purchaseStore.show" class="px-6 py-2.5 rounded-xl font-bold text-xs text-[var(--text-main)] bg-[#5865F2] hover:bg-[#4752C4] transition">Войти через Discord</button></div><div v-else class="grid grid-cols-1 md:grid-cols-3 gap-6"><div class="md:col-span-1 space-y-6"><div class="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-2xl p-6"><span class="text-xs text-[var(--text-muted)] font-medium">Статус проходки</span><div class="mt-2 mb-4"><div v-if="pass?.has_pass" class="inline-flex items-center gap-1.5 px-3 py-1 rounded-lg bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 text-xs font-bold"><ShieldCheck :size="14" /> Проходка активна</div><div v-else class="inline-flex items-center gap-1.5 px-3 py-1 rounded-lg bg-amber-500/10 border border-amber-500/20 text-amber-400 text-xs font-bold"><AlertTriangle :size="14" /> Без проходки</div></div><button v-if="!pass?.has_pass" @click="purchaseStore.show" class="w-full py-2.5 rounded-xl font-bold text-xs text-[var(--text-main)] bg-gradient-to-r from-[#0080FF] to-[#00BBFF] hover:opacity-90 transition">Купить проходку</button><a v-else href="http://localhost:1420" class="w-full py-2.5 rounded-xl font-bold text-xs text-center text-[var(--text-main)] bg-gradient-to-r from-[#0080FF] to-[#00BBFF] hover:opacity-90 transition flex items-center justify-center gap-2"><Download :size="14" /> Скачать лаунчер</a></div><div class="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-2xl p-6 text-xs space-y-3 text-[var(--text-muted)]"><div class="flex justify-between"><span class="text-slate-500">Игровой ник:</span><strong class="text-[var(--text-main)]">{{ user?.username }}</strong></div><div class="flex justify-between"><span class="text-slate-500">Discord:</span><strong class="text-[var(--text-main)]">{{ discord?.discord_username || 'Привязан' }}</strong></div></div></div><div class="md:col-span-2 bg-[var(--bg-card)] border border-[var(--border-color)] rounded-2xl p-6"><h3 class="font-heading text-lg font-bold text-[var(--text-main)] mb-2">Кастомный скин</h3><p class="text-xs text-[var(--text-muted)] mb-6 leading-relaxed">Поддерживаются стандартные PNG-скины. Скин моментально синхронизируется на сервере.</p><div class="space-y-4 max-w-md"><div><label class="block text-xs font-medium text-[var(--text-muted)] mb-2">Файл скина (.png)</label><label class="w-full border border-dashed border-white/10 hover:border-[#0080FF]/50 bg-white/[0.02] hover:bg-[var(--bg-card-hover)] transition rounded-xl p-4 flex flex-col items-center justify-center cursor-pointer text-center group"><Upload :size="20" class="text-[var(--text-muted)] group-hover:text-[#0099FF] transition mb-2" /><span class="text-xs font-medium text-[var(--text-muted)] group-hover:text-[var(--text-main)] transition">{{ skinFile ? skinFile.name : 'Нажмите для выбора файла скина' }}</span><span class="text-[11px] text-slate-500 mt-1">Стандартный PNG-скин до 1 МБ</span><input type="file" accept="image/png" class="hidden" @change="onFileSelect" /></label></div><button :disabled="!skinFile" @click="uploadSkin" class="px-5 py-2.5 rounded-xl font-bold text-xs text-[var(--text-main)] bg-gradient-to-r from-[#0080FF] to-[#00BBFF] disabled:opacity-40 transition flex items-center gap-2"><Upload :size="14" /> Загрузить скин</button><p v-if="statusMsg" class="text-xs text-emerald-400 mt-2">{{ statusMsg }}</p></div><div class="mt-3"><SkinPreview3D :skin-url="skinPreviewUrl" /></div></div></div></div></main></template>
